# PUT /api/sheets/{sheetId}/claims/{claimId}/status — change a claim's status by an action: open
# (DRAFT to OPEN), settle (OPEN to SETTLED, or to PENDING when a clerk settles a claim whose due is above the sheet's
# clerk limit), approve (PENDING to SETTLED) or reject with a reason (PENDING back to OPEN), both by a steward, or void
# (DRAFT, OPEN or PENDING to VOID), or resettle by a steward (SETTLED again, its due fixed anew at today's figure as
# an open claim bound by no statement). An action the claim's status does not allow, a claim dated inside a closed period,
# settling or approving by the user who opened the claim, settling or approving a claim with no proofs whose due is above
# the proof threshold in force on its date (checked before the clerk limit), approving, rejecting or re-settling by a clerk, a rejection without a
# reason, or an unknown action, is a 409 and a claim not on the sheet a 404, neither writing anything. Opening gives
# the claim the sheet's next number and records who opened it; a voided claim keeps its number. Responds with the
# claim as stored.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimStatus
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimStatusChanged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
# POST /api/sheets/{sheetId}/bulk-settle — settle the selected claims together. Each selected claim is settled by the
# signed-in user exactly as the single settle does (see ApplyClaimStatus), in list order: people in the order they were
# added, a person's claims newest first; one that goes to PENDING counts as settled, and each writes its own
# CLAIM_SETTLED or CLAIM_PENDING and figure lines. Each that cannot be settled (or is not on the sheet) is left as it is
# and counted refused. Responds with how many were settled and how many refused.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkSettle
  next: settle
settle:
  class: net.officefloor.hq.app.claim.SettleClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkSettle
# POST /api/sheets/{sheetId}/people/{personId}/hold — add a hold on a person from a date (blank: the sheet's today) until
# an optional to-date; a person may have several holds over time. A date that is not yyyy-MM-dd, or a to-date before the
# from-date, is a 400 and a person not on the sheet a 404, none writing anything. Only the person's OPEN (or PENDING)
# claims dated within a hold, and not bound by a statement, count in no live total. Responds with the person as stored.
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonHold
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_OPENED, CLAIM_SETTLED, CLAIM_PENDING, CLAIM_APPROVED, CLAIM_REJECTED, CLAIM_VOIDED or CLAIM_RESETTLED to the audit
 * file once the status is stored, ending with number=<number> when the claim has one; CLAIM_SETTLED and CLAIM_APPROVED
 * then end with the due they fixed (due=n/a when its grade had no rate), CLAIM_REJECTED with reason=<reason>, CLAIM_RESETTLED with old=<previous due> new=<new due>. Then writes the
 * figures the change moved (see Rollup). */
public class RecordClaimStatusChanged {
    public void record(@Val Claim claim, @Val ClaimStatusChange change, @Val ClaimNumber number, @Val PreviousDue previous,
            PersonRepository people, @Val RollupBefore before, Rollup rollup, Audit audit) {
        String event = switch (change.action()) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLE -> claim.status() == ClaimStatus.PENDING ? "CLAIM_PENDING" : "CLAIM_SETTLED";
            case APPROVE -> "CLAIM_APPROVED";
            case REJECT -> "CLAIM_REJECTED";
            case VOID -> "CLAIM_VOIDED";
            case RESETTLE -> "CLAIM_RESETTLED";
        };
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record(event + " sheet=" + claim.sheetId() + " by=" + change.by() + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date() + (number.value() == null ? "" : " number=" + number.value())
                + (change.action() == ClaimAction.RESETTLE
                        ? " old=" + figure(previous.value()) + " new=" + figure(claim.due())
                        : claim.status() == ClaimStatus.SETTLED
                        ? " due=" + (claim.due() == null ? "n/a" : claim.due().toPlainString()) : "")
                + (change.action() == ClaimAction.REJECT ? " reason=" + change.reason() : ""));
        rollup.record(claim.sheetId(), change.by(), before);
    }

    private static String figure(BigDecimal due) {
        return due == null ? "n/a" : due.toPlainString();
    }
}
