package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: each date is blank or yyyy-MM-dd. */
public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<Hold> hold) throws InvalidPersonException {
        LocalDate from = date(request == null ? null : request.from(), "from");
        LocalDate to = date(request == null ? null : request.to(), "to");
        hold.set(new Hold(from, to, request == null || request.by() == null ? "" : request.by().trim()));
    }

    private static LocalDate date(String value, String which) throws InvalidPersonException {
        String text = value == null ? "" : value.trim();
        if (text.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("The hold's " + which + "-date must be yyyy-MM-dd");
        }
    }
}
package net.officefloor.hq.app.person;

/** Body of holding a person: the from-date (blank: the sheet's today), the optional to-date, and who holds them. */
public record HoldRequest(String from, String to, String by) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds a hold on the person from the from-date (the sheet's today when blank) until the to-date, if any; a to-date
 *  before the from-date is refused. Publishes the hold as added (its from-date filled in). */
public class HoldPerson {
    public void hold(@Val Person person, @Val Hold hold, SheetRepository sheets, PersonRepository people,
            Out<Person> held, Out<PersonHold> added) throws InvalidPersonException {
        LocalDate from = hold.from() != null ? hold.from() : sheets.today(person.sheetId());
        if (hold.to() != null && hold.to().isBefore(from)) {
            throw new InvalidPersonException("The hold's to-date must not be before its from-date");
        }
        PersonHold span = new PersonHold(from, hold.to());
        people.hold(person.sheetId(), person.id(), span);
        List<PersonHold> holds = new ArrayList<>(person.holds());
        holds.add(span);
        holds.sort(Comparator.comparing(PersonHold::from));
        held.set(new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version(),
                person.retiredFrom(), person.grades(), List.copyOf(holds)));
        added.set(span);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes PERSON_HELD to the audit file once the hold is stored. Then writes the figures the change moved (see Rollup). */
public class RecordPersonHold {
    public void record(@Val Person person, @Val Hold hold, @Val PersonHold added, @Val RollupBefore before, Rollup rollup,
            Audit audit) {
        audit.record("PERSON_HELD sheet=" + person.sheetId() + " by=" + hold.by() + " name=" + person.name() + " from="
                + added.from());
        rollup.record(person.sheetId(), hold.by(), before);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A person on a sheet: a name (unique on the sheet, case ignored; kept without surrounding spaces) and a grade, one of A, B or C.
 *  The grade is dated: {@code grades} are the grades recorded, by from-date (the one with none, the first given, first), and
 *  {@code grade} is the one in force on the sheet's today.
 *  The version is 0 when added and goes up by one on each stored edit. {@code retiredFrom} (yyyy-MM-dd) is the date the
 *  person is retired from, null when not retired; a person with one counts as retired at once, whatever the date.
 *  {@code holds} are the person's holds, by from-date: an OPEN or PENDING claim of theirs dated within one, and not bound by
 *  a statement, counts in no live total. {@code held} is whether they have any hold. */
public record Person(long id, String sheetId, String name, String grade, long version, String retiredFrom, boolean held,
        List<PersonGrade> grades, List<PersonHold> holds) {

    public Person(long id, String sheetId, String name, String grade, long version, String retiredFrom,
            List<PersonGrade> grades, List<PersonHold> holds) {
        this(id, sheetId, name, grade, version, retiredFrom, !holds.isEmpty(), grades, holds);
    }

    /** Whether a hold of the person covers the date. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch((h) -> h.covers(date));
    }

    public boolean retired() {
        return retiredFrom != null;
    }

    /** Whether a claim of the person may be dated {@code date}: not after their retirement date. */
    public boolean mayClaimOn(java.time.LocalDate date) {
        return retiredFrom == null || !date.isAfter(java.time.LocalDate.parse(retiredFrom));
    }

    /** The grade in force on a date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        return gradeOn(grades, date);
    }

    /** The grade in force on a date among these, by from-date; null when there are none. */
    public static String gradeOn(List<PersonGrade> grades, LocalDate date) {
        PersonGrade found = null;
        for (PersonGrade g : grades) {
            if (g.from() != null && g.from().isAfter(date)) {
                continue;
            }
            if (found == null || found.from() == null || (g.from() != null && g.from().isAfter(found.from()))) {
                found = g;
            }
        }
        return found == null ? null : found.grade();
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The stored people, kept per sheet. Ids are assigned in the order people are added. A person's grades are kept
 *  dated in person_grade, and their holds in person_hold; a person read carries them all, and the grade in force on the
 *  sheet's today. */
@Repository
public class PersonRepository {

    private static final String COLUMNS = "id, sheet_id, name, version, retired_from";

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public PersonRepository(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    public List<Person> list(String sheetId) {
        return withGrades(sheetId, jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY id",
                PersonRepository::map, sheetId));
    }

    public Person find(String sheetId, long id) {
        return first(sheetId, jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
                PersonRepository::map, sheetId, id));
    }

    /** The person on the sheet with this name, case ignored; null when there is none. */
    public Person findByName(String sheetId, String name) {
        return first(sheetId, jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND name_key = LOWER(?)",
                PersonRepository::map, sheetId, name));
    }

    private Person first(String sheetId, List<Person> found) {
        return found.isEmpty() ? null : withGrades(sheetId, found).get(0);
    }

    /** The people with their grades and holds, and the grade in force on the sheet's today. */
    private List<Person> withGrades(String sheetId, List<Person> found) {
        if (found.isEmpty()) {
            return found;
        }
        Map<Long, List<PersonGrade>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ? ORDER BY person_id, from_date NULLS FIRST",
                (ResultSet rs) -> {
                    Date from = rs.getDate("from_date");
                    grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new PersonGrade(rs.getString("grade"), from == null ? null : from.toLocalDate()));
                }, sheetId);
        Map<Long, List<PersonHold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY person_id, from_date, id",
                (ResultSet rs) -> {
                    Date to = rs.getDate("to_date");
                    holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new PersonHold(rs.getDate("from_date").toLocalDate(), to == null ? null : to.toLocalDate()));
                }, sheetId);
        LocalDate today = sheets.today(sheetId);
        List<Person> people = new ArrayList<>();
        for (Person p : found) {
            List<PersonGrade> mine = List.copyOf(grades.getOrDefault(p.id(), List.of()));
            people.add(new Person(p.id(), p.sheetId(), p.name(), Person.gradeOn(mine, today), p.version(), p.retiredFrom(),
                    mine, List.copyOf(holds.getOrDefault(p.id(), List.of()))));
        }
        return people;
    }

    /** Whether a person on the sheet other than {@code exceptId} (0: anyone) has this name, case ignored. */
    public boolean nameTaken(String sheetId, String name, long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND id <> ?",
                Integer.class, sheetId, name, exceptId);
        return n != null && n > 0;
    }

    /** The unique (sheet_id, name_key) index refuses a name taken by a concurrent add or edit. */
    public Person add(String sheetId, String name, String grade) throws DuplicatePersonNameException {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        try {
            jdbc.update(con -> {
                PreparedStatement ps = con.prepareStatement("INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)",
                        new String[] { "id" });
                ps.setString(1, sheetId);
                ps.setString(2, name);
                ps.setString(3, grade);
                return ps;
            }, keys);
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(name);
        }
        long id = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, NULL, ?)", sheetId, id, grade);
        return new Person(id, sheetId, name, grade, 0, null, List.of(new PersonGrade(grade, null)), List.of());
    }

