import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { peopleKey, type Person } from '../people/people';
import { usePersonRowAction } from '../people/rowAction';

function HoldHead() {
  return (
    <>
      <th>On hold</th>
      <th />
    </>
  );
}

/** Whether the person has any hold, their holds (one line each), and the dates and button that add one: from the
 *  from-date (blank: the sheet's today) until the to-date (blank: open-ended). Only their OPEN or PENDING claims dated
 *  within a hold, and not bound by a statement, count in no live total. A refused hold shows the row's error. */
function PersonHold({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const submit = useSubmitOnce();
  const rowAction = usePersonRowAction(sheetId, person.id, 'hold');
  const hold = useMutation({
    mutationFn: (dates: { from: string; to: string }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/hold`, { ...dates, by: user }),
    onSuccess: () => {
      setFrom('');
      setTo('');
      return queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <>
      <td data-testid="person-hold">{person.held ? 'yes' : 'no'}</td>
      <td>
        {(person.holds ?? []).map((h, i) => (
          <div key={i} data-testid="person-hold-line">
            {h.from} – {h.to ?? ''}
          </div>
        ))}
        <input
          data-testid="person-hold-from"
          placeholder="from yyyy-MM-dd"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            hold.reset();
          }}
        />{' '}
        <input
          data-testid="person-hold-to"
          placeholder="to yyyy-MM-dd"
          value={to}
          onChange={(e) => {
            setTo(e.target.value);
            hold.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-hold-toggle"
          disabled={hold.isPending}
          onClick={() => {
            if (!submit.begin()) return;
            rowAction.take();
            hold.reset();
            hold.mutate({ from: from.trim(), to: to.trim() });
          }}
        >
          Hold
        </button>
        {hold.isError && rowAction.isLatest && <span data-testid="person-error"> Could not hold this person.</span>}
      </td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 50, Component: HoldHead }),
  PersonRow.fill({ order: 50, Component: PersonHold }),
];
import { useCallback, useSyncExternalStore } from 'react';

// The action last taken on each person's row (by sheet and person id). A row shows one error at a time: an action's
// error shows only while it is the latest action taken on that row, so taking the next action clears the last error.
const latest = new Map<string, string>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Marks `action` as the latest taken on the person's row (call when it is taken), and whether it still is. */
export function usePersonRowAction(sheetId: string, personId: number, action: string) {
  const key = `${sheetId}\u0000${personId}`;
  const current = useSyncExternalStore(subscribe, () => latest.get(key));
  const take = useCallback(() => {
    latest.set(key, action);
    listeners.forEach((l) => l());
  }, [key, action]);
  return { take, isLatest: current === undefined || current === action };
}
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/** Header cells of the people table: one `<th>` per column a feature adds to every person's row. */
export const PeopleHead = defineSlot<{ sheetId: string; user: string }>('people.head');

/** Cells of a person's row in the people table: each contribution renders its own `<td>`s, in
 *  the same order as its PeopleHead cells. */
export const PersonRow = defineSlot<{ sheetId: string; user: string; person: Person }>('person.row');
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** That the person `personId` has named `patronId`, another person on the sheet, as a patron. */
export type Patron = { personId: number; patronId: number };

export const patronsKey = (sheetId: string) => ['sheet', sheetId, 'patrons'];

/** Every patron named on the sheet. */
export function usePatrons(sheetId: string) {
  return useQuery({
    queryKey: patronsKey(sheetId),
    queryFn: () => getJson<Patron[]>(`/api/sheets/${encodeURIComponent(sheetId)}/patrons`),
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { live, useClaims } from '../claims/claims';
import { usePeople, type Person } from '../people/people';
import { personDue, sum, useRates } from '../rates/rates';
import { useCap, useFloor, useLate } from '../settings/settings';
import { patronsKey, usePatrons, type Patron } from './patrons';

function PatronsHead() {
  return (
    <>
      <th>Patrons</th>
      <th>Backing</th>
      <th />
    </>
  );
}

/** A person's patrons (names, sorted), their backing (their patrons' due-totals added up, skipping n/a; 0.00 with no
 *  patrons), and the picker that names another person on the sheet as a patron. A refused add shows the row's
 *  patron error. */
function PersonPatrons({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const people = usePeople(sheetId);
  const patrons = usePatrons(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const cap = useCap(sheetId);
  const queryClient = useQueryClient();
  const [chosen, setChosen] = useState('');

  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Patron>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/patrons`, { patronId, by: user }),
    onSuccess: () => {
      setChosen('');
      return queryClient.invalidateQueries({ queryKey: patronsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  const mine = (patrons.data ?? [])
    .filter((p) => p.personId === person.id)
    .map((p) => people.data?.find((q) => q.id === p.patronId))
    .filter((p): p is Person => p !== undefined);
  const names = mine.map((p) => p.name).sort((a, b) => a.localeCompare(b));
  const backing = sum(
    mine.map((p) =>
