package net.officefloor.hq.app.patron;

import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the patron's id is required. */
public class ValidatePatron {
    public void validate(@RequestBody PatronRequest request, Out<PatronAdd> add) throws InvalidPersonException {
        if (request == null || request.patronId() == null) {
            throw new InvalidPersonException("The patron is required");
        }
        add.set(new PatronAdd(request.patronId(), request.by() == null ? "" : request.by().trim()));
    }
}
-- The people a person has named as their patrons: other people on the same sheet, each at most once.
CREATE TABLE patron (
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    PRIMARY KEY (sheet_id, person_id, patron_id)
);
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

